  --chart-1:             #d97a4d;
  --chart-2:             #5fa0aa;
  --chart-3:             #7fb583;
  --chart-4:             #d1a862;
  --chart-5:             #9a9a90;

  --sidebar:             #0e0f11;
  --sidebar-foreground:  #eceef0;
  --sidebar-primary:     #d97a4d;
  --sidebar-primary-foreground: #121316;
  --sidebar-accent:      #24262b;
  --sidebar-accent-foreground: #eceef0;
  --sidebar-border:      rgba(255, 255, 255, 0.09);
  --sidebar-ring:        #d97a4d;
}

/* ── GLOBAL TOKEN PROPS (inline styles, JS, chart fills) ── */
:root {
  /* Status colours */
  --clr-online:     #5c8a5f;
  --clr-offline:    #7a7a70;
  --clr-stale:      #b08a3f;
  --clr-alert:      #b8562f;
  --clr-critical:   #b3402f;
  --clr-new:        #4c7a82;
  --clr-resolved:   #5c8a5f;
  --clr-suspect:    #b08a3f;

  /* Accent scale */
  --clr-accent-hi:  #b8562f;
  --clr-accent-mid: #7a7a70;
  --clr-accent-lo:  #52525b;

  /* Category chart colours */
  --clr-industrial:  #b8562f;
  --clr-commercial:  #4c7a82;
  --clr-residential: #5c8a5f;
  --clr-drs:         #b08a3f;
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
  }
  html {
    @apply font-sans;
  }
}

/*
 * ══════════════════════════════════════════════════════════════
 *  GLOBAL DARK-MODE SLATE OVERRIDE
 *  Maps every Tailwind dark:bg-slate-*, dark:border-slate-*,
 *  dark:text-slate-* class to the warm earthy palette so that
 *  pages not yet migrated to CSS-var tokens still get the
 *  correct colour theme automatically.
 * ══════════════════════════════════════════════════════════════
 */

/* ── Backgrounds ── */
.dark .dark\:bg-slate-950,
.dark .dark\:bg-slate-950\/50,
.dark .dark\:bg-slate-950\/70,
.dark .dark\:bg-slate-950\/80 {
  background-color: #30291f !important;
}
.dark .dark\:bg-slate-900,
.dark .dark\:bg-slate-900\/60,
.dark .dark\:bg-slate-900\/80 {
  background-color: #3f372b !important;
}
.dark .dark\:bg-slate-800,
.dark .dark\:bg-slate-800\/40,
.dark .dark\:bg-slate-800\/60 {
  background-color: #4d4128 !important;
}
.dark .dark\:bg-slate-700 {
  background-color: #5a4b31 !important;
}

/* ── Borders ── */
