  border-color: rgba(194, 157, 102, 0.22) !important;
}
.dark .dark\:border-slate-700 {
  border-color: rgba(194, 157, 102, 0.35) !important;
}

/* ── Text ── */
.dark .dark\:text-slate-100 {
  color: #f7f1e8 !important;
}
.dark .dark\:text-slate-200 {
  color: #edddca !important;
}
.dark .dark\:text-slate-300 {
  color: #d8c8b1 !important;
}
.dark .dark\:text-slate-400 {
  color: #c8b99f !important;
}
.dark .dark\:text-slate-500 {
  color: #8d8570 !important;
}
.dark .dark\:text-white {
  color: #f7f1e8 !important;
}

/* ── Hover backgrounds ── */
.dark .dark\:hover\:bg-slate-800:hover,
.dark .dark\:hover\:bg-slate-800\/40:hover,
.dark .dark\:hover\:bg-slate-800\/60:hover {
  background-color: #4d4128 !important;
}
.dark .dark\:hover\:bg-slate-100:hover {
  background-color: #4d4128 !important;
}

/* ── Hover text ── */
.dark .dark\:hover\:text-slate-200:hover {
  color: #edddca !important;
}
.dark .dark\:hover\:text-white:hover {
  color: #f7f1e8 !important;
}

/* ── Native select / input surfaces ── */
select,
input[type="text"],
input[type="date"],
input[type="search"] {
  background-color: var(--card);
  border-color: var(--input);
  color: var(--foreground);
}

select::placeholder,
input[type="text"]::placeholder,
input[type="date"]::placeholder,
input[type="search"]::placeholder {
