import {
  downloadCustomerReportExcel,
  downloadRangeSummaryExcel,
  groupReadingsByMeter,
} from "@/lib/report-excel";
import type {
  CustomerReport,
  CustomerRangeReport,
  ReportMode,
  RangeSelectorType,
  DataFrequency,
} from "@/features/reports";
import { FREQUENCY_OPTIONS } from "@/features/reports";
