                        <input
                          type="checkbox"
                          checked={selectedCustomerIds.length === customers.length && customers.length > 0}
                          onChange={(e) => {
                            if (e.target.checked) {
                              setSelectedCustomerIds(customers.map((c) => c.id));
                            } else {
                              setSelectedCustomerIds([]);
                            }
