                        ))}
                      </select>
                    </div>
                  )}
                </>
              )}
            </div>

            {reportMode === "dateRange" && (
              <div className="grid grid-cols-1 md:grid-cols-4 gap-4 items-end">
                <div className="space-y-2">
                  <label className="text-sm font-medium text-muted-foreground">Data Frequency</label>
                  <select
