                  (!reportData || (reportData.meters?.length ?? 0) === 0)) ||
                (activeReportMode === "rangeSelection" && !rangeReportData)
              }
              variant="outline"
              className="border-border bg-card hover:bg-accent text-foreground"
            >
              {exporting ? (
                <RefreshCw className="w-4 h-4 mr-2 animate-spin" />
