                      <TableHead className="text-muted-foreground font-semibold whitespace-nowrap">
                        Meter Serial
                      </TableHead>
                      <TableHead className="text-muted-foreground font-semibold whitespace-nowrap">
                        Start Date
                      </TableHead>
                      <TableHead className="text-muted-foreground font-semibold whitespace-nowrap text-right">
                        Start Value (Sm³)
                      </TableHead>
                      <TableHead className="text-muted-foreground font-semibold whitespace-nowrap">
                        End Date
                      </TableHead>
                      <TableHead className="text-muted-foreground font-semibold whitespace-nowrap text-right">
                        End Value (Sm³)
                      </TableHead>
                      <TableHead className="text-muted-foreground font-semibold whitespace-nowrap text-right">
                        Consumption (Sm³)
                      </TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {rangeReportData.meters.map((meter) => (
